const productCatalogSchema = { 
    "$schema": "http://json-schema.org/draft-07/schema#", 
    "type": "object", 
    "required": ["products"], 
    "properties": { 
        "products": { 
            "type": "array", 
            "items": { 
                "type": "object", 
                "required": ["id", "title", "handle"], 
                "properties": { 
                    "id": { "type": "string" }, 
                    "title": { "type": "string" }, 
                    "handle": { "type": "string" }
                } 
            } 
        }
    } 
}; 


pm.test("[Contract Validation] GET /products adheres to Ajv JSON Schema", function () { 
    pm.response.to.have.jsonSchema(productCatalogSchema); 
});

