const cartResponseSchema = { 

    "$schema": "http://json-schema.org/draft-07/schema#", 

    "type": "object", 

    "required": ["cart"], 

    "properties": { 

        "cart": { 

            "type": "object", 

            "required": ["id", "items", "region_id", "currency_code"], 

            "properties": { 

                "id": { "type": "string" }, 

                "region_id": { "type": "string" }, 

                "currency_code": { "type": "string" }, 

                "items": { 

                    "type": "array", 

                    "items": { 

                        "type": "object", 

                        "required": ["id", "title", "quantity", "unit_price", "variant_id"], 

                        "properties": { 

                            "id": { "type": "string" }, 

                            "title": { "type": "string" }, 

                            "quantity": { "type": "number" }, 

                            "unit_price": { "type": "number" }, 

                            "variant_id": { "type": "string" } 

                        } 

                    } 

                } 

            } 

        } 

    } 

}; 



pm.test("[Contract Validation] GET /carts/{{cartId}} adheres to Ajv JSON Schema", function () { 

    pm.response.to.have.jsonSchema(cartResponseSchema); 

});

const baseUrl = pm.environment.get("baseUrl");
const cartId = pm.environment.get("cartId");
const apiKey = pm.variables.get("publishable_api_key");

pm.sendRequest({
    url: baseUrl + "/shipping-options?cart_id=" + cartId,
    method: "GET",
    header: { "x-publishable-api-key": apiKey }
}, function (err, res) {
    if (!err && res.code === 200) {
        const options = res.json().shipping_options;
        if (options && options.length > 0) {
            pm.environment.set("shippingOptionId", options[0].id);
            console.log("Set shippingOptionId: " + options[0].id);
        } else {
            console.error("No shipping options for this cart/region.");
        }
    } else {
        console.error("Failed to fetch shipping options", err || res.json());
    }
});

const baseUrl = pm.environment.get("baseUrl");
const cartId = pm.environment.get("cartId");
const apiKey = pm.variables.get("publishable_api_key");

// Step 1: Automatically fetch cart details to get the region_id
pm.sendRequest({
    url: baseUrl + "/carts/" + cartId,
    method: "GET",
    header: {
        "x-publishable-api-key": apiKey
    }
}, function (err, cartRes) {
    if (!err && cartRes.code === 200) {
        let cart = cartRes.json().cart;
        let regionId = cart.region_id;
        console.log("Automatically found regionId: " + regionId);

        // Step 2: Fetch payment providers using the extracted region_id
        pm.sendRequest({ 
            url: baseUrl + "/payment-providers?region_id=" + regionId, 
            method: "GET",
            header: {
                "x-publishable-api-key": apiKey
            }
        }, function (err, providerRes) { 
            if (!err && providerRes.code === 200) { 
                let providers = providerRes.json().payment_providers; 
                if (providers && providers.length > 0) { 
                    pm.environment.set("providerId", providers[0].id); 
                    console.log("Successfully set providerId: " + providers[0].id);
                } else {
                    console.error("No payment providers available for this region.");
                } 
            } else {
                console.error("Failed to fetch payment providers", err || providerRes.json());
            } 
        });

        // Step 3: Automatically create Payment Collection and save its ID
        pm.sendRequest({
            url: baseUrl + "/payment-collections",
            method: "POST",
            header: {
                "x-publishable-api-key": apiKey,
                "Content-Type": "application/json"
            },
            body: {
                mode: "raw",
                raw: JSON.stringify({ cart_id: cartId })
            }
        }, function (err, pcRes) {
            if (!err && (pcRes.code === 200 || pcRes.code === 201)) {
                let pcId = pcRes.json().payment_collection.id;
                pm.environment.set("paymentCollectionId", pcId);
                console.log("Successfully set paymentCollectionId: " + pcId);
            } else {
                console.error("Failed to create payment collection", err || pcRes.json());
            }
        });

    } else {
        console.error("Failed to fetch cart details", err || cartRes.json());
    }
});

